{"implementation": "def solve(case):
    wti = case['word_token_indices']
    wl = case['word_labels']
    tc = case['token_count']
    if len(wti) != len(wl):
        raise ValueError('mismatch')
    all_indices = []
    for group in wti:
        all_indices.extend(group)
    if len(all_indices) != tc:
        raise ValueError('total tokens mismatch')
    if set(all_indices) != set(range(tc)):
        raise ValueError('out of range or missing')
    token_labels = [0] * tc
    for i, group in enumerate(wti):
        label = wl[i]
        for idx in group:
            token_labels[idx] = label
    kept = [i for i, lbl in enumerate(token_labels) if lbl == 1]
    return {"kept_indices": kept, "token_labels": token_labels}"}
